import sqlite3

def setup_db():
    conn = sqlite3.connect('magaza.db')
    cursor = conn.cursor()

    # Tabloları temizle ve yeniden oluştur
    cursor.executescript('''
    DROP TABLE IF EXISTS iadeler;
    DROP TABLE IF EXISTS siparis_kalemleri;
    DROP TABLE IF EXISTS siparisler;
    DROP TABLE IF EXISTS urunler;
    DROP TABLE IF EXISTS musteriler;

    CREATE TABLE musteriler (id INTEGER PRIMARY KEY, ad TEXT NOT NULL, sehir TEXT NOT NULL, kayit_tarihi TEXT NOT NULL);
    CREATE TABLE urunler (id INTEGER PRIMARY KEY, ad TEXT NOT NULL, kategori TEXT NOT NULL, fiyat REAL NOT NULL);
    CREATE TABLE siparisler (id INTEGER PRIMARY KEY, musteri_id INTEGER NOT NULL, tarih TEXT NOT NULL, FOREIGN KEY(musteri_id) REFERENCES musteriler(id));
    CREATE TABLE siparis_kalemleri (siparis_id INTEGER NOT NULL, urun_id INTEGER NOT NULL, adet INTEGER NOT NULL, birim_fiyat REAL NOT NULL, FOREIGN KEY(siparis_id) REFERENCES siparisler(id), FOREIGN KEY(urun_id) REFERENCES urunler(id));
    CREATE TABLE iadeler (id INTEGER PRIMARY KEY, siparis_id INTEGER NOT NULL, urun_id INTEGER NOT NULL, adet INTEGER NOT NULL, FOREIGN KEY(siparis_id) REFERENCES siparisler(id), FOREIGN KEY(urun_id) REFERENCES urunler(id));
    ''')

    # Veri Ekleme
    cursor.executescript('''
    INSERT INTO musteriler (id, ad, sehir, kayit_tarihi) VALUES (1, 'Ali', 'İstanbul', '2023-01-01'), (2, 'Ayşe', 'Ankara', '2023-02-01');
    INSERT INTO urunler (id, ad, kategori, fiyat) VALUES (1, 'Laptop', 'Elektronik', 15000), (2, 'Mouse', 'Elektronik', 200), (3, 'Klavye', 'Elektronik', 500), (4, 'Monitor', 'Elektronik', 3000), (5, 'Kulaklık', 'Elektronik', 100);
    INSERT INTO siparisler (id, musteri_id, tarih) VALUES (1, 1, '2023-03-01'), (2, 2, '2023-03-02'), (3, 1, '2023-03-03');

    -- Laptop: 10 adet satıldı, 2 iade edildi -> Net 8. Fiyat: 15000. Ciro: 8 * 15000 = 120000? 
    -- Hayır, soruya göre net ciro hesaplaması: her kalem bazında (adet - iade) * birim_fiyat.
    -- Sipariş 1: 1x Laptop (15000) -> İade yok.
    -- Sipariş 2: 2x Mouse (200), 1x Klavye (500) -> Mouse için 1 adet iade.
    -- Sipariş 3: 1x Laptop (15000), 3x Kulaklık (100) -> Laptop için 1 adet iade.

    -- Sipariş 1: 1x Laptop (15000)
    INSERT INTO siparis_kalemleri VALUES (1, 1, 1, 15000);
    -- Sipariş 2: 2x Mouse (200), 1x Klavye (500)
    INSERT INTO siparis_kalemleri VALUES (2, 2, 2, 200);
    INSERT INTO siparis_kalemleri VALUES (2, 3, 1, 500);
    -- Sipariş 3: 1x Laptop (15000), 3x Kulaklık (100)
    INSERT INTO siparis_kalemleri VALUES (3, 1, 1, 15000);
    INSERT INTO siparis_kalemleri VALUES (3, 5, 3, 100);

    -- İadeler:
    -- Mouse (Sipariş 2, Ürün 2): 1 adet iade
    INSERT INTO iadeler (siparis_id, urun_id, adet) VALUES (2, 2, 1);
    -- Laptop (Sipariş 3, Ürün 1): 1 adet iade
    INSERT INTO iadeler (siparis_id, urun_id, adet) VALUES (3, 1, 1);
    ''')

    conn.commit()
    conn.close()

setup_db()
print("Veritabanı hazırlandı.")

